UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Doctor of Counselling at The University of Notre Dame Australia is a professional Doctorate research-based program leading to a thesis of approximately 80,000 words in length.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 146190,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-5"> <p>The following criteria apply to students seeking admission to the Professional Doctorate program:</p><ul><li>The Pro Vice Chancellor-Research, on the advice of the Dean of the School, determines admission to the Doctor of Counselling Award.</li><li>Applicants to the Doctor of Counselling Award are expected to satisfy the following criteria: <ul><li>Possession of a research Masters degree by thesis or dissertation appropriate to the professional field of the applicant; or</li><li>Possession of a Masters degree by coursework appropriate to the professional field of the applicant completed at a superior standard; or</li><li>Possession of a Bachelor’s degree with Honours (typically 1st Class or Class 2A Honours level or equivalent); or</li><li>Possession of a Master of Philosophy; or</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Doctoral level.</li></ul><p>In addition to the academic criteria listed above, applicants are normally expected to satisfy the following:</p><ul><li>have a minimum of 3 years of relevant professional practice;</li><li>have the support of an industry or professional mentor.</li></ul><p>You may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</p></li></ul> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/arts-and-sciences/postgraduate/doctor-of-counselling',
    updated_at = NOW()
WHERE cricos_course_code = '074299G';

