    course_description = '<h4>Course overview</h4><p>A Master of Philosophy with a Major in Business at The University of Notre Dame Australia is an undergraduate program for high-achieving students that includes a supervised research thesis.</p>',
    course_duration_per_week = 78,
    offshore_tuition_fee = 86726,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_Requirements-2"> <p>The following criteria apply to students seeking admission to the Master of Philosophy program:</p><ul><li>Possession of an undergraduate degree from a recognised university, which has been completed at a high credit standard and which demonstrates the applicant’s potential to undertake and complete research-based study.</li><li>An equivalent academic background or extensive professional experience that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Masters level.</li></ul><p>You may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</p> </div>',
