UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Graduate Certificate in Business from Notre Dame University, will give you an understanding of multiple aspects of business and can be a stepping stone to further study.</p>',
    course_duration_per_week = 26,
    offshore_tuition_fee = 34356,
    onshore_tuition_fee = NULL,
    enrolment_fee = 137,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <ul><li>A Bachelor’s degree from a recognised Australian or overseas university demonstrating the attainment of satisfactory grades OR</li><li>Relevant industry experience in management/supervision.</li></ul><p>Note: Recognition of Prior Learning may be granted to selected applicants who have no formal tertiary qualifications but who have at least 10 years’ industry experience. For further information go to <a href="https://www.notredame.edu.au/current-students/your-enrolment/admin-and-fees/fremantle/advanced-standing" title="Advanced Standing Fremantle">Advanced Standing</a><u>.</u></p> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-business/postgraduate/graduate-certificate-in-business',
    updated_at = NOW()
WHERE cricos_course_code = '092768A';

UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>Our Master of Business Administration offers flexible entry pathways & can be completed in 18 months with recognition of prior learning. online or on campus.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/admission-requirements"> University’s minimum requirements for admission for postgraduate programs</a>.</p><p><strong>Specific Program Requirements for Admission</strong></p><p>To be eligible for admission to the program, an applicant must hold:</p><ul><li>an AQF Level 7 qualification; or</li><li>studies sufficient to meet the requirements of an AQF Level 7 Award; or</li><li>informal/non-formal learning equivalent to an AQF Level 7 qualification plus evidence of the skills necessary to complete postgraduate studies.</li></ul><p>International students must have a qualification that is recognised as equivalent to an Australian Bachelor’s degree, AQF Level 7.</p><p>Applicants who have successfully completed subjects at another University, which are relevant to the selected program of study, may be eligible for <a href="https://www.notredame.edu.au/study/applications-and-admissions/recognition-of-prior-learning">Advanced Standing</a>.</p> </div>',
