UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>A Master of Philosophy (Education) at The University of Notre Dame Australia is a flexible research degree for postgraduates wishing to expand their career through research.</p>',
    course_duration_per_week = 78,
    offshore_tuition_fee = 86726,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p>To be eligible for admission to the Master of Philosophy applicants must also meet the following specific requirements.</p><ul><li>Applicants to the master’s program are expected to satisfy the following criteria:<ul><li>Possession of a Bachelor’s degree (AQF level 7 qualification); or</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the National Head of School to be an appropriate preparation for independent study and research work at master’s level.</li></ul></li></ul><p>An applicant may be required to satisfy the National Head of School of the ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</p><!--<p>Applicants should normally fulfill one of the following criteria:</p> <ul> <li>Possess an undergraduate degree from a recognised university, which has been completed at a high credit standard and which demonstrates the applicant&rsquo;s potential to undertake and complete research-based study;</li> <li>Have an equivalent academic background or extensive professional experience that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Master''''s level.</li> </ul> <p>In addition, an applicant may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study or as deemed by the Dean of School.</p>--> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-education/postgraduate/master-of-philosophy-education',
    updated_at = NOW()
WHERE cricos_course_code = '078924M';

