UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>A Bachelor of Biomedical Science at The University of Notre Dame Australia provides a gateway to a rewarding career in various health-related fields.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 114666,
    onshore_tuition_fee = NULL,
    enrolment_fee = 1095,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <h3 class="q">Entry requirements WA</h3><div class="svara">Academic requirements for this program are outlined below. In addition, to be eligible for admission, all applicants need to satisfy the Minimum University <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">Admission Requirements</a> outlined. These include those relating to minimum age and <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements/english-language-requirements">English Language Proficiency</a>. We also consider your application more broadly – your non-academic achievements (such as any previous leadership roles, volunteering, work, church and/or community involvement) as well as personal qualities - your aspirations and interests and your capacity to complete your chosen program. See <a href="https://www.notredame.edu.au/forms/admissions/applying-to-notre-dame-individual-factors">Individual Factors</a> for further details regarding this. <p class="svara"><strong>Applicants with recent Secondary Education</strong></p><ul><li>Prescribed ATAR/Selection Rank* of 70</li></ul><p>OR</p><ul><li>Equivalent International Baccalaureate (IB) score of 25</li></ul><p>*Selection Ranks include ATAR plus <a href="https://www.notredame.edu.au/study/applications-and-admissions/how-to-apply/adjustment-factors">Adjustment Factors</a>.</p><p><strong>Applicants with Higher Education Study</strong></p><ul><li>Successful completion of 4 subjects at an undergraduate level or higher*</li></ul><p>OR</p><ul><li>Successful completion of the Notre Dame Tertiary Pathway Program (TPP), or a tertiary preparation program from another institution that is deemed to be of a similar academic rigour to the Notre Dame TPP</li></ul><p>*Applicants who have successfully completed subjects at another University, which are relevant to the selected program of study, may be eligible for credit (<a href="https://www.notredame.edu.au/study/applications-and-admissions/recognition-of-prior-learning" target="_blank">Advanced Standing</a>).</p><p><strong>Applicants with Vocational Education and Training (VET) study</strong></p><ul><li>Successful completion of AQF Certificate IV or higher from an accredited provider such as TAFE or a Registered Training Organisation (RTO)</li></ul><p><strong>Applicants with Work and Life Experience</strong></p><p>Applicants who left secondary education more than two years previously and who have not undertaken VET or higher education study since may be considered for direct entry. This includes applicants who have completed Steiner, Montessori or home school curriculums. To qualify, applicants must be 20 years of age as at 1 March in the year of intake and meet one or more of the following:</p><ul><li>Applicants who have completed at least two years of relevant work experience may be considered for direct entry. Applicants must provide evidence of their work experience, including duties undertaken and years of experience, and they must demonstrate that they have the academic capability to undertake undergraduate studies. The Special Tertiary Admissions Test (STAT) may be required.^</li></ul><p>OR</p><ul><li>Completion of STAT with scores of at least 135 in the Multiple Choice section and 140 in the Written English section.^</li></ul><p>OR</p><ul><li>Completion of two Year 12 WACE, HSC or equivalent exams, with a result equivalent to the Indicative ATAR/Selection Rank listed under Secondary Education section above.</li></ul><p>^STAT results must have been obtained within the last three calendar years in order to be considered (e.g. for 2024 admission, STAT results obtained in 2023, 2022 or 2021 can be considered). <br/><em>Please note: all applicants must be of school leaving age or older to apply.</em></p></div><h3 class="q">Entry requirements NSW</h3><div class="svara">Academic requirements for this program are outlined below. In addition, to be eligible for admission, all applicants need to satisfy the Minimum University <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">Admission Requirements</a> outlined. These include those relating to minimum age and <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements/english-language-requirements">English Language Proficiency</a>. We also consider your application more broadly – your non-academic achievements (such as any previous leadership roles, volunteering, work, church and/or community involvement) as well as personal qualities - your aspirations and interests and your capacity to complete your chosen program. See <a href="https://www.notredame.edu.au/forms/admissions/applying-to-notre-dame-individual-factors">Individual Factors</a> for further details regarding this. <p><strong>Applicants with recent Secondary Education</strong></p><ul><li>Prescribed ATAR/Selection Rank*</li></ul><p>OR</p><ul><li>Equivalent International Baccalaureate (IB) score</li></ul><p>*Selection Ranks include ATAR plus <a href="https://www.notredame.edu.au/study/applications-and-admissions/how-to-apply/adjustment-factors">Adjustment Factors</a>.</p><p><strong>Applicants with Higher Education Study</strong></p><ul><li>Successful completion of at least 4 subjects at an undergraduate level or higher*</li></ul><p>OR</p><ul><li>Successful completion of the Notre Dame <a href="https://www.notredame.edu.au/forms/admissions/admission-criteria">Tertiary Pathway Program </a>(TPP), or a tertiary preparation program from another institution that is deemed to be of a similar academic rigour to the Notre Dame TPP</li></ul><p>*Applicants who have successfully completed subjects at another University, which are relevant to the selected program of study, may be eligible for credit <a href="https://www.notredame.edu.au/study/applications-and-admissions/recognition-of-prior-learning">(Advanced Standing)</a>.</p><p><strong>Applicants with Vocational Education and Training (VET) study</strong></p><ul><li>Successful completion of AQF Diploma or higher from an accredited provider such as TAFE or a Registered Training Organisation (RTO)</li></ul><p><strong>Applicants with Work and Life Experience</strong></p><p>Applicants who left secondary education more than two years previously and who have not undertaken VET or higher education study since may be considered for direct entry. This includes applicants who have completed Steiner, Montessori or home school curriculums. To qualify, applicants must be 20 years of age as at 1 March in the year of intake and meet one or more of the following:</p><ul><li>Applicants who have completed at least two years of relevant work experience may be considered for direct entry. Applicants must provide evidence of their work experience, including duties undertaken and years of experience, and they must demonstrate that they have the academic capability to undertake undergraduate studies. The Special Tertiary Admissions Test (STAT) may be required.^</li></ul><p>OR</p><ul><li>*Completion of STAT with scores of at least 150 in the Multiple Choice section and 150 in the Written English section.^</li></ul><p>OR</p><ul><li>*Completion of two Year 12 HSC, WACE or equivalent exams, with a result equivalent to the Indicative ATAR/Selection Rank listed under Secondary Education section above.</li></ul><p>^STAT results must have been obtained within the last three calendar years in order to be considered (e.g. for 2024 admission, STAT results obtained in 2023, 2022 or 2021 can be considered).</p><p><em>Please note: all applicants must be of school leaving age or older to apply.</em></p></div> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-health-sciences/undergraduate/bachelor-of-biomedical-science',
    updated_at = NOW()
WHERE cricos_course_code = '049306M';

UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>A Doctor of Health Sciences at The University of Notre Dame Australia is a specialised degree that combines coursework and research with reliable workplace connections.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 146190,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-5"> <p>The following criteria apply to students seeking admission to the Professional Doctorate program:</p><ul><li>The Pro Vice-Chancellor-Research, on the advice of the Dean of the School, determines admission to the Doctor of Health Sciences Award.</li><li>Applicants to the Doctor of Health Sciences Award are expected to satisfy the following criteria: <ul><li>Possession of a research Masters degree by thesis or dissertation appropriate to the professional field of the applicant; or</li><li>Possession of a Masters degree by coursework appropriate to the professional field of the applicant completed at a superior standard; or</li><li>Possession of a Bachelor’s degree with Honours (typically 1st Class or Class 2A Honours level or equivalent); or</li><li>Possession of a Master of Philosophy; or</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Doctoral level.</li></ul></li><li>In addition to the academic criteria listed above, applicants are normally expected to satisfy the following: <ul><li>have a minimum of 3 years of relevant professional practice;</li><li>have the support of an industry or professional mentor.</li></ul></li></ul><p>You may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</p> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-health-sciences/postgraduate/doctor-of-health-sciences',
    updated_at = NOW()
WHERE cricos_course_code = '074300J';

