UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>This thesis-based postgraduate degree program is available in a number of disciplines, including Philosophy and Theology.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 146190,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" title="Admission requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: <em>Admissions</em>.</p><p>To be eligible for admission to the Doctor of Philosophy applicants must also meet the following specific requirements:</p><ul type="disc"><li>The Pro Vice Chancellor-Research, on the advice of the National Head of School, determines admission to the Doctor of Philosophy Award.</li><li>Applicants to the Doctor of Philosophy Award are expected to satisfy the following criteria:<ul><li>Possession of a research Masters appropriate to the professional field of the applicant; or</li><li>Possession of a Bachelor’s degree with Honours (typically 1st Class or Class 2A Honours level or equivalent); or</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the National Head of School to be an appropriate preparation for independent study and research work at Doctoral level.</li></ul></li></ul> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-health-sciences/postgraduate/doctor-of-philosophy-health-sciences',
    updated_at = NOW()
WHERE cricos_course_code = '011396F';

