    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p>To be eligible for admission to the Masters by Research, applicants must meet the following specific requirements:</p><ul><li>Possession of an undergraduate degree from a recognised University, which has been completed at a superior standard and which demonstrates the applicant’s potential to undertake and complete a research-based study at AQF level 9 equivalence.</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the National Head of School to be an appropriate preparation for independent study and research work at Masters level.</li></ul><p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf" target="_blank">University’s Policy: Admission and Credit</a>.</p> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-law/postgraduate/master-of-laws-research',
    updated_at = NOW()
WHERE cricos_course_code = '073036F';

