    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p style="border:none">Applicants will usually have to fulfil the following criteria:</p><ul><li>Possess an undergraduate degree from a recognised university, which has been completed at a high credit standard and which demonstrates the applicant’s potential to undertake and complete research-based study.</li></ul><p>OR</p><ul><li>Have an equivalent academic background or extensive professional experience that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Master''''s level.</li><li>Candidates may be required to satisfy the Dean of the School of the ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</li></ul> </div>',
