    offshore_tuition_fee = 182092,
    onshore_tuition_fee = NULL,
    enrolment_fee = 1460,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p> <div id="component_417280"> <!---Expander Dropdown----> <!---- Alternative drop down styling for pages that require an accordion component. Drop down uses text links with a text field that expands on-click function. Used on content and landing pages ---> <style> a.anchor { display: block; position: relative; top: -90px; visibility: hidden; } .svara { display:none; margin-left:40px;} .q { cursor:pointer; margin-left:40px;} .q:hover { text-decoration:underline; } .accordion {margin-top:50px;} </style> <script> $( document ).ready(function() { $(".q").click(function(){ if ( $(this).is(":visible") ) { $x=1; } else {$x=0; } $(this).next(".svara").toggle(''''300''''); }); }); </script> </div> </p><h3 class="q">Entry requirements WA</h3><div class="svara"> <div id="wa_band_8_416336"> <p>Academic requirements for this program are outlined below. In addition, to be eligible for admission, all applicants need to satisfy the Minimum University <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" title="Admission requirements">Admission Requirements</a> outlined. These include those relating to minimum age and <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements/english-language-proficiency-requirements" title="English language proficiency requirements">English Language Proficiency</a>. We also consider your application more broadly – your non-academic achievements (such as any previous leadership roles, volunteering, work, church and/or community involvement) as well as personal qualities - your aspirations and interests and your capacity to complete your chosen program. See <a href="https://www.notredame.edu.au/forms/admissions/applying-to-notre-dame-individual-factors" target="_blank" title="Individual factors">Individual Factors</a> for further details regarding this.</p><p><strong>Applicants with recent Secondary Education</strong></p><p>Indicative ATAR/Selection Rank* of 90</p><p>OR</p><p>International Baccalaureate (IB) score of 34</p><p>*Selection Ranks include ATAR plus <a href="https://www.notredame.edu.au/study/applications-and-admissions/how-to-apply/adjustment-factors" title="Adjustment factors">Adjustment Factors</a>.</p><p>Note: In order to be a competitive applicant, it is strongly preferred that school leavers have studied an ATAR course or equivalent in English and Mathematics and at least one ATAR course in the sciences that include:</p><ul><li>Physics;</li><li>Chemistry;</li><li>Human Biology, and/or</li><li>Physical Education studies</li></ul><p><strong>Applicants with Higher Education</strong></p><ul><li>Successful completion of at least 8 subjects at an undergraduate level or higher*, with an average grade of 65% or higher.</li></ul><p>Applicants who have successfully completed subjects at another University, which are relevant to the selected program of study, may be eligible for credit (<a href="https://www.notredame.edu.au/study/applications-and-admissions/recognition-of-prior-learning" title="Advanced standing">Advanced Standing</a>).</p><p><em>Note: In order to be a competitive applicant, it is strongly preferred that previous studies undertaken be in a health or science related area, at either an undergraduate or postgraduate level.</em></p><p><em>Note: Tertiary Preparation Programs are not accepted for entry.</em></p><p><strong>Applicants with Vocational Education and Training (VET) study</strong></p><ul><li>VET qualifications are not accepted for entry.</li></ul><p><strong>Applicants with Work and Life Experience</strong></p><ul><li>Work and Life Experience is not accepted for entry.</li><li>STAT is not accepted for entry.</li></ul><!--<p>Applicants to the School of Education require a completed AQF Diploma or higher in a relevant discipline.</p>--> </div> </div> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-health-sciences/undergraduate/bachelor-of-physiotherapy',
    updated_at = NOW()
WHERE cricos_course_code = '045167E';

UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>A Doctor of Physiotherapy (Research) degree is a professional doctorate designed to meet the needs of professional physiotherapists through research.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 146190,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-5"> <p>The following criteria apply to students seeking admission to the Professional Doctorate program:</p><ul><li>The Pro Vice-Chancellor-Research, on the advice of the Dean of the School, determines admission to the Doctor of Physiotherapy Research Award.</li><li>Applicants to the doctoral program are expected to satisfy the following criteria: <ul><li>Possession of a research Masters degree by thesis or dissertation appropriate to the professional field of the applicant; or</li><li>Possession of a Masters degree by coursework appropriate to the professional field of the applicant completed at a superior standard; or</li><li>Possession of a Bachelor’s degree with Honours (typically 1st Class or Class 2A Honours level or equivalent); or</li><li>Possession of a Master of Philosophy; or</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Doctoral level.</li></ul></li><li>In addition to the academic criteria listed above, applicants are normally expected to satisfy the <ul><li>have a minimum of 3 years of relevant professional practice;</li><li>have the support of an industry or professional mentor.</li></ul></li></ul><p>You may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</p> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-health-sciences/postgraduate/doctor-of-physiotherapy-research',
    updated_at = NOW()
WHERE cricos_course_code = '075781A';

