UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>A Master of Nursing (Research) at The University of Notre Dame Australia is designed for registered nurses who wish to advance their careers through research.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 86726,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p>In order to be considered for entry, applicants are expected to satisfy the following criteria:</p><ul><li>Current license to practice as a Registered Nurse within Australia or provisional registration whichever is applicable at the time of the students program commencement; or</li><li>Applicants who do not meet the requirements of the clause above, but are able to demonstrate equivalent international experience satisfy the criteria. In these circumstances, an applicant’s research topic may be limited to a non-clinical setting; and</li><li>Bachelor of Nursing or other appropriate degree; and</li><li>Minimum of two years relevant post registration nursing experience, or as acceptable by the program coordinator; and</li><li>An applicant may be required to satisfy the Dean of the School of Nursing and Midwifery of the ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</li></ul> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-nursing/postgraduate/master-of-nursing-research',
    updated_at = NOW()
