UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Master of Professional Psychology (MPP) at Notre Dame is a one-year program that offers psychology graduates a 5th year of study as an essential step towards accreditation as a general psychologist.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 34078,
    onshore_tuition_fee = NULL,
    enrolment_fee = 275,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the University’s minimum requirements for admission. The requirements for admission are detailed in the <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf" target="_blank">University’s Policy: Admission and Credit</a>.</p><p><strong>Individual advice or feedback regarding applications will not be provided to applicants during the application process or at the conclusion of the application cycle.</strong></p><p><strong>Specific Program Requirements for Admission</strong></p><p>To be eligible for admission to the program, an applicant must meet the following requirements:</p><ol start="1" type="1"><li>Completion of an Australian Psychology Accreditation Council (APAC) accredited 4-year sequence of study in Psychology within the last 10 years, with a minimum of Second-Class Honours Division B or equivalent;</li><li>Be eligible for provisional registration as a psychologist (NB students must obtain and provide evidence of provisional registration from the Psychology Board of Australia before commencing the program and maintain it over the course of their program);</li><li>Demonstrate suitability to undertake the course as evidence by satisfactory: <ol start="1" type="a"><li>Referee reports via <a href="https://psychologyreference.zendesk.com/auth/v2/login/signin" target="_blank">Psychology Reference Portal</a>;</li><li>CV and personal statement; and</li><li>For short-listed candidates, interview with the selection committee.</li></ol></li></ol><p><strong>More information</strong></p><ul><li>Referee reports:<ul><li>Applicants are required to register with the Psychology Reference System and nominate two referees (1 x academic and 1 x professional). Referees will be invited to complete an online reference form.</li><li>Submission of two academic references in place of a professional reference, or vice versa, will not be accepted.</li><li>Only references submitted through the Psychology Reference System by the application closing date will be accepted.</li><li>Applicants should request for their referees to complete the online reference at least two weeks prior to the application closing date, to ensure sufficient time for submission.</li><li>References submitted after the deadline will not be accepted.</li></ul></li><li>CV: Maximum length of two A4 pages.</li><li>Personal statement: Maximum one A4 page providing a reflective account of the candidate’s motivation as well as why they believe they are well-suited to join the program and peruse a career as a psychologist</li></ul><p>Please note that the application process is competitive, and the university can only accept a limited number of students into the program due to supervision requirements. This means that not all applicants who meet the minimum eligibility requirements will necessarily be interviewed. Short listing will take into consideration academic achievement and professional suitability.</p><p>Given that admission is on a competitive basis, requests to study at a different campus after the interview or after an offer has been accepted will not be acceded to. Applicants will only be considered for and offered a place at the campus at which they applied and interviewed for.</p><p>Students who have obtained their qualifications outside Australia must have their qualifications assessed prior to applying for this program and prior to applying for registration with the psychology board of Australia. The Australian psychological society (APS) provides this assessment service for the board and the assessment assists the board in determining if the student’s qualifications are equivalent to an ‘approved qualification.’ However, the final decision on equivalence rests with the board.</p><p>If you obtained your qualifications outside Australia, please submit evidence of your APS equivalency with your application.</p><p>We welcome and encourage Aboriginal and Torres Strait Islander applicants to apply.</p><p>Applicants who have successfully completed subjects at another University, which are relevant to the selected program of study, may be eligible for <a href="https://www.notredame.edu.au/study/applications-and-admissions/recognition-of-prior-learning">Advanced Standing</a>.</p><p>The application deadline for Semester 1 2027 intake is Thursday, 15 October 2026. Late applications will not be accepted. Interviews are expected to take place in November 2026.</p> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/arts-and-sciences/postgraduate/master-of-professional-psychology',
    updated_at = NOW()
WHERE cricos_course_code = '117079E';

UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Master of Physiotherapy is an accelerated 2-year full-time graduate-entry program that prepares graduates to become effective, culturally-appropriate practitioners eligible for registration as a physiotherapist with the Australian Health Practitioner Registration Agency.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 133920,
    onshore_tuition_fee = NULL,
    enrolment_fee = 827,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the<a href="https://www.notredame.edu.au/study/admission-requirements"> University’s minimum requirements for admission for postgraduate programs</a>.</p><p>International applicants must hold a qualification equivalent to an Australian Bachelor’s degree (AQF Level 7) or be in the final year of an eligible Bachelor’s degree.</p><p>Admission to the Master of Physiotherapy is competitive. Meeting the minimum entry or subject requirements does not guarantee an offer of admission.</p><p><strong>Assessment of Subject Requirements for Admission</strong></p><p>In addition to the entry requirements above, an applicant must also meet the following:</p><ul><li>A Bachelor of Exercise and Sports Science with a minimum GPA of 2.5**; OR</li><li>A Bachelor of Science with a major or specialisation in Exercise and Sports Science, with a minimum GPA of 2.5**; OR</li><li>Any Bachelor''''s degree* with a minimum GPA of 2.5**, AND assessed studies in: Human Anatomy &amp; Physiology, Human Pathophysiology, collectively known as “subject requirements”.</li><li>Inherent requirements as listed in the <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/351747/Master-of-Physiotherapy.pdf" target="_blank">Program Requirements</a>.</li></ul><p><em>*Applicants must have completed two semesters of Human Anatomy and one semester of Pathophysiology (eg. <a href="https://www.notredame.edu.au/about-us/faculties-and-schools/school-of-health-sciences/fremantle/course-descriptions" title="Course Descriptions">HLTH1000, PHTY1006 and PHTY1007</a>).</em></p><p><em>**GPA of 2.5 is based on a 4-point scale.</em></p><p>Applicants who have successfully completed subjects at another University, which are relevant to the selected program of study, may be eligible for <a href="https://www.notredame.edu.au/study/applications-and-admissions/recognition-of-prior-learning">Advanced Standing</a>.</p><p><strong>Applicants in the Final Year of the Qualifying Degree</strong></p><p>Applicants who are enrolled in the final year of undergraduate degree must complete all requirements of the degree successfully as of close of business on 23 December 2026. Admissions Office must receive an official transcript indicating completion of the degree or a certificate of completion from the University Administration before this deadline. As the Master of Physiotherapy program commences in early 2027, an extension cannot be granted. Applicants may wish to note this stipulated deadline and request for the relevant documentation from their University in a timely manner.</p> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-health-sciences/postgraduate/master-of-physiotherapy',
    updated_at = NOW()
WHERE cricos_course_code = '114346D';

