UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>The Bachelor of Exercise & Sport Science (Assured Pathway) provides a pathway into our Master of Physiotherapy and onto a career as a physiotherapist.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 114666,
    onshore_tuition_fee = NULL,
    enrolment_fee = 1095,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p> <div id="component_417280"> <!---Expander Dropdown----> <!---- Alternative drop down styling for pages that require an accordion component. Drop down uses text links with a text field that expands on-click function. Used on content and landing pages ---> <style> a.anchor { display: block; position: relative; top: -90px; visibility: hidden; } .svara { display:none; margin-left:40px;} .q { cursor:pointer; margin-left:40px;} .q:hover { text-decoration:underline; } .accordion {margin-top:50px;} </style> <script> $( document ).ready(function() { $(".q").click(function(){ if ( $(this).is(":visible") ) { $x=1; } else {$x=0; } $(this).next(".svara").toggle(''''300''''); }); }); </script> </div> </p><h3 class="q">Entry requirements WA</h3><div class="svara"> <div id="wa_exercise_&amp;_sports_sci_to_physio_801097"> <p>Academic requirements for this program are outlined below. In addition, to be eligible for admission, all applicants need to satisfy the Minimum University <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" title="Admission requirements">Admission Requirements</a> outlined. These include those relating to minimum age and <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements/english-language-proficiency-requirements" title="English language proficiency requirements">English Language Proficiency</a>. We also consider your application more broadly – your non-academic achievements (such as any previous leadership roles, volunteering, work, church and/or community involvement) as well as personal qualities - your aspirations and interests and your capacity to complete your chosen program. See <a href="https://www.notredame.edu.au/forms/admissions/applying-to-notre-dame-individual-factors" target="_blank" title="Individual factors">Individual Factors</a> for further details regarding this.</p><p><strong>Applicants with recent Secondary Education</strong></p><ul><li>Indicative ATAR/Selection Rank* of 85</li></ul><p>OR</p><ul><li>International Baccalaureate (IB) score of 32</li></ul><p>*No Adjustment Factors are available for this Program.</p><p><strong>Applicants with Higher Education Study</strong></p><ul><li>Successful completion of at least 4 subjects at an undergraduate level or higher*, with an average grade of 65% or higher</li></ul><p>*Applicants who have successfully completed subjects at another University, which are relevant to the selected program of study, may be eligible for credit <a href="https://www.notredame.edu.au/study/applications-and-admissions/recognition-of-prior-learning" title="Recognition of prior learning">(Advanced Standing)</a>.</p><p><em>Note: Tertiary Preparation Programs are not accepted for entry.</em></p><p><strong>Applicants with Vocational Education and Training (VET) study</strong></p><ul><li>Successful completion of AQF Diploma or higher from an accredited provider such as TAFE or a Registered Training Organisation (RTO)</li></ul><p><strong>Applicants with Work and Life Experience</strong></p><p>Applicants who left secondary education more than two years previously and who have not undertaken VET or higher education study since may be considered for direct entry. This includes applicants who have completed Steiner, Montessori or home school curriculums. To qualify, applicants must be 20 years of age as at 1 March in the year of intake and meet one or more of the following:</p><ul><li>Applicants who have completed at least two years of relevant work experience may be considered for direct entry. Applicants must provide evidence of their work experience, including duties undertaken and years of experience, and they must demonstrate that they have the academic capability to undertake undergraduate studies. The Special Tertiary Admissions Test (STAT) may be required.</li></ul><p>OR</p><ul><li>Completion of STAT with scores of at least 160 in the Multiple Choice section <strong>and</strong> 160 in the Written English section.</li></ul><p>OR</p><ul><li>Completion of two Year 12 WACE, HSC or equivalent exams, with a result equivalent to the Indicative ATAR/Selection Rank listed under Secondary Education section above.</li></ul><p>*STAT results must have been obtained within the last three calendar years in order to be considered (e.g. for 2024 admission, STAT results obtained in 2023, 2022 or 2021 can be considered).</p><p><em>Please note: all applicants must be of school leaving age or older to apply.</em></p><!--<p>Applicants to the School of Education require a completed AQF Diploma or higher in a relevant discipline.</p>--> </div> </div><h3 class="q">Entry requirements NSW</h3><div class="svara"> <div id="nsw_exercise_&amp;_sports_sci_to_physio_801067"> <p>Academic requirements for this program are outlined below. In addition, to be eligible for admission, all applicants need to satisfy the Minimum University <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" title="Admission requirements">Admission Requirements</a> outlined. These include those relating to minimum age and <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements/english-language-proficiency-requirements" title="English language proficiency requirements">English Language Proficiency</a>. We also consider your application more broadly – your non-academic achievements (such as any previous leadership roles, volunteering, work, church and/or community involvement) as well as personal qualities - your aspirations and interests and your capacity to complete your chosen program. See <a href="https://www.notredame.edu.au/forms/admissions/applying-to-notre-dame-individual-factors" target="_blank" title="Individual factors">Individual Factors</a> for further details regarding this.</p><p><strong>Applicants with recent Secondary Education</strong></p><ul><li>Prescribed ATAR/Selection Rank*</li></ul><p>OR</p><ul><li>Equivalent International Baccalaureate (IB) score</li></ul><p>*No Adjustment Factors are available for this Program.</p><p><strong>Applicants with Higher Education Study</strong></p><ul><li>Successful completion of at least 4 subjects at an undergraduate level or higher*, with an average grade of 65% or higher</li></ul><p>*Applicants who have successfully completed subjects at another University, which are relevant to the selected program of study, may be eligible for credit <a href="https://www.notredame.edu.au/study/applications-and-admissions/recognition-of-prior-learning" title="Recognition of prior learning">(Advanced Standing)</a>.</p><p><em>Note: Tertiary Preparation Programs are not accepted for entry.</em></p><p><strong>Applicants with Vocational Education and Training (VET) study</strong></p><ul><li>Successful completion of AQF Diploma or higher from an accredited provider such as TAFE or a Registered Training Organisation (RTO)</li></ul><p><strong>Applicants with Work and Life Experience</strong></p><p>Applicants who left secondary education more than two years previously and who have not undertaken VET or higher education study since may be considered for direct entry. This includes applicants who have completed Steiner, Montessori or home school curriculums. To qualify, applicants must be 20 years of age as at 1 March in the year of intake and meet one or more of the following:</p><ul><li>Applicants who have completed at least two years of relevant work experience may be considered for direct entry. Applicants must provide evidence of their work experience, including duties undertaken and years of experience, and they must demonstrate that they have the academic capability to undertake undergraduate studies. The Special Tertiary Admissions Test (STAT) may be required.</li></ul><p>OR</p><ul><li>Completion of STAT with scores of at least 170 in the Multiple Choice section <strong>and</strong> 170 in the Written English section.</li></ul><p>OR</p><ul><li>Completion of two Year 12 WACE, HSC or equivalent exams, with a result equivalent to the Indicative ATAR/Selection Rank listed under Secondary Education section above.</li></ul><p>*STAT results must have been obtained within the last three calendar years in order to be considered (e.g. for 2024 admission, STAT results obtained in 2023, 2022 or 2021 can be considered).</p><p><em>Please note: all applicants must be of school leaving age or older to apply.</em></p><!--<p>Applicants to the School of Education require a completed AQF Diploma or higher in a relevant discipline.</p>--> </div> </div> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-health-sciences/undergraduate/bachelor-of-exercise-and-sport-science-assured',
    updated_at = NOW()
