UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>A Master of Primary Teaching at The University of Notre Dame Australia can transition you into primary school teaching over two years of full-time study.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 72802,
    onshore_tuition_fee = NULL,
    enrolment_fee = 551,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: Admission and Credit.</p><p><strong> </strong></p><p><strong>Specific Program Requirements for Admission </strong></p><p>To be eligible for admission to the Master of Primary Teaching applicants must also meet the following specific requirements.</p><ul type="disc"><li>This award is only available to those who hold a Bachelor degree from a recognised Higher Education Provider.</li><li>Applicants who have not successfully completed their Primary education in an English- speaking country will be required to sit the IELTS Academic Test and achieve a minimum overall score of 7.5 in IELTS Academic, with no score lower than 8.0 in speaking and listening, and no score lower than 7.0 in reading and writing.</li></ul> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-education/postgraduate/master-of-primary-teaching',
    updated_at = NOW()
WHERE cricos_course_code = '116882H';

UPDATE courses SET
    course_description = '<h4>Course overview</h4><p>A Master of Secondary Teaching at The University of Notre Dame Australia enables you to transition into a secondary teaching career in the specialised field of your choosing.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 72802,
    onshore_tuition_fee = NULL,
    enrolment_fee = 551,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div class="accordion__content" id="Entry_requirements-3"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: Admission and Credit.</p><p><strong>Specific Program Requirements for Admission </strong></p><p>To be eligible for admission to the Master of Secondary Teaching applicants must also meet the following specific requirements.</p><ul><li>This award is only available to those who hold a bachelor degree from a recognised Higher Education Provider.</li><li>Applicants who have not successfully completed their Secondary education in an English-speaking country will be required to sit the IELTS Academic Test and achieve a minimum overall score of 7.5 in IELTS Academic, with no score lower than 8.0 in speaking and listening, and no score lower than 7.0 in reading and writing.</li><li><div role="presentation">Applicants must have successfully completed a Bachelor degree or equivalent qualification with a minimum of six courses in an area of study offered by UNDA.</div></li><li><div role="presentation">Applicants may also be admitted with a second teaching area (usually at least 4 units) in a discipline area relevant to the secondary school curriculum.</div></li></ul> </div>',
    apply_form = 'https://www.notredame.edu.au/programs/school-of-education/postgraduate/master-of-secondary-teaching',
    updated_at = NOW()
WHERE cricos_course_code = '116883G';

